using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CursedFlagOmenData", menuName = "Data/Battle/Omens System/Omen Data/Anomaly/CursedFlagOmenData")]
public class CursedFlagOmenData : OnStartOfTurnOmenData
{
	[Header("Cursed Flag")]
	[SerializeField]
	private int[] valuesBasedOnChapter;

	[SerializeField]
	private MapHandler mapHandler;

	public override void ActivateOmen(GameObject target = null)
	{
		ActivateOmen(valuesBasedOnChapter[mapHandler.CurrentAreaIndex], target);
	}
}
